def build():
 p=Paper('F06')
 def add(s,z,e,label,tex,pages,ass,defs,steps,scope,keys=None,kind='derivation',role='proof',assessment='no_statement_error_recorded',leanrole=None,original=None,proof=None,proofpages=None,symbols=None):
  id='decoder-'+s;aa,ae=items(id,'assumption',ass);dd,de=items(id,'definition',defs);ps=[];pe=[]
  for k,(tz,te,bz,be,ft,ln) in enumerate(steps,1):
   sid=f'{id}-step-{k}';ps.append(dict(id=sid,title=tz,body_md=bz,formula_tex=ft,justification='',lean_refs=ln));pe.append(dict(id=sid,title=te,body_md=be,justification='',lean_refs=ln))
  keys=keys or []
  orig=original if original is not None else '\n\n'.join(source(k)['original_statement_md'] for k in keys)
  pr=proof if proof is not None else '\n\n'.join(source(k)['original_proof_md'] for k in keys if source(k)['original_proof_md'])
  if not orig:raise ValueError('Missing author statement '+id)
  pp=proofpages if proofpages is not None else sorted(set(q for k in keys if source(k)['original_proof_md'] for q in source(k)['source_pages']))
  lr=list(dict.fromkeys(n for step in ps for n in step['lean_refs']));er=leanrole or ('theorem_proof' if role=='proof' and lr else 'counterexample' if role=='counterexample' and lr else 'partial_component' if lr else 'none')
  scz,sce=scope
  row=dict(id=id,paper_id=p.pid,title=z,kind=kind,original_label=label,inventory_ids=[id],source_refs=[p.ref('formal',pages,label)],statement_tex=tex,assumptions=aa,definitions=dd,original_statement_md=orig,original_proof_md=pr,original_proof_refs=[p.ref('formal',pp,label)] if pp else [],original_statement_source_type='complete_manual_formal_statement_transcription',original_proof_source_type='complete_manual_formal_proof_transcription' if pr else 'no_local_author_proof',source_transcription_notes=[],overview=ps[0]['body_md'] if ps else z,proof_steps=ps,shared_proof_ids=[],symbol_ids=['decoder-'+x for x in(symbols or ['grid','input-spectrum','kernel-response','som'])],notation_map=[],rewrite_status='complete',rewrite_role=role,proof_scope='full_original_statement' if role=='proof' else 'counterexample_to_original_clause' if role=='counterexample' else 'explicit_component_and_source_scope',statement_assessment=assessment,alignment_status='agent_reviewed_original_statement_preserved',user_review_status='pending',scope=scz,lean=dict(status='pending_verification' if lr else 'not_available',compiled=False,evidence_role=er,declarations=lr,scope=scz,translations={'en':{'scope':sce}}),related_issue_ids=[],translations={'en':dict(title=e,overview=pe[0]['body_md'] if pe else e,assumptions=ae,definitions=de,proof_steps=pe,notation_map=[],scope=sce)})
  p.rows.append(row)
  if pr:
   (p.D/'original-proofs').mkdir(exist_ok=True);(p.D/'original-proofs'/f'{id}.md').write_text(pr+'\n')
  return row
 build_core(p,add);build_moments(p,add);build_defects(p,add);build_analysis(p,add);merge_discussion(p)
