def add_shared(p):
 # Expose actual reusable proofs without copying paper-specific false targets.
 picks=[('orthogonality','fourier-grid'),('forward-convolution','circular-correlation'),('gaussian-response','real-gaussian-response'),('single-channel-moments','independent-frequency-products')]
 for suffix,shared in picks:
  row=next(r for r in p.rows if r['id']=='decoder-'+suffix);sp={k:copy.deepcopy(row[k]) for k in ['title','statement_tex','assumptions','definitions','overview','proof_steps','symbol_ids','rewrite_status','scope','lean','translations']}
  sid='shared-decoder-'+shared;sp.update(id=sid,rewrite_role='proof',proof_scope='exact_shared_statement',statement_assessment='no_statement_error_recorded')
  sp['lean']['evidence_role']='theorem_proof'
  for q,qe in zip(sp['proof_steps'],sp['translations']['en']['proof_steps']):
   q['id']=q['id'].replace(row['id'],sid);qe['id']=qe['id'].replace(row['id'],sid)
  p.shared.append(sp);row['shared_proof_ids'].append(sid)

